def p(text='', bold=False):
    para=doc.add_paragraph()
    rr=para.add_run(text);rr.bold=bold
    return para

def h(text):return doc.add_heading(text,2)

def step(number,title,text):
    para=doc.add_paragraph()
    para.add_run(f'{number}. {title} ').bold=True
    para.add_run(text)
    return para

def note(label,text):
    para=doc.add_paragraph()
    para.add_run(label+' ').bold=True
    para.add_run(text)
    return para

def code(text):
    para=doc.add_paragraph()
    para.paragraph_format.space_before=Pt(3)
    para.paragraph_format.space_after=Pt(8)
    rr=para.add_run(text);rr.font.name='Courier New';rr.font.size=Pt(9)
    return para

def link(label,url):
    para=doc.add_paragraph()
    hyper=OxmlElement('w:hyperlink')
    rel=para.part.relate_to(url,'http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink',is_external=True)
    hyper.set(qn('r:id'),rel)
    run=OxmlElement('w:r');rp=OxmlElement('w:rPr')
    color=OxmlElement('w:color');color.set(qn('w:val'),'175A8A');rp.append(color)
    under=OxmlElement('w:u');under.set(qn('w:val'),'single');rp.append(under)
    run.append(rp);t=OxmlElement('w:t');t.text=label;run.append(t);hyper.append(run);para._p.append(hyper)

def table(headers, rows, widths):
    t=doc.add_table(rows=1, cols=len(headers))
    t.alignment=WD_TABLE_ALIGNMENT.CENTER
    t.autofit=False
    for c,w in zip(t.columns,widths):c.width=Cm(w)
    tpr=t._tbl.tblPr
    borders=OxmlElement('w:tblBorders')
    for name in ['top','left','bottom','right','insideH','insideV']:
        e=OxmlElement('w:'+name);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');borders.append(e)
    tpr.append(borders)
    margins=OxmlElement('w:tblCellMar')
    for name, val in [('top','90'),('bottom','90'),('left','115'),('right','115')]:
        e=OxmlElement('w:'+name);e.set(qn('w:w'),val);e.set(qn('w:type'),'dxa');margins.append(e)
    tpr.append(margins)
    for c,txt,w in zip(t.rows[0].cells,headers,widths):c.text=txt;c.width=Cm(w)
    repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in rows:
        cells=t.add_row().cells
        for c,txt,w in zip(cells,row,widths):c.text=str(txt);c.width=Cm(w)
    for i,row in enumerate(t.rows):
        cant=OxmlElement('w:cantSplit');row._tr.get_or_add_trPr().append(cant)
        for c in row.cells:
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'333333' if i==0 else ('F4F6F8' if i%2==0 else 'FFFFFF'));c._tc.get_or_add_tcPr().append(shade)
            for para in c.paragraphs:
                para.paragraph_format.space_after=Pt(2)
                para.paragraph_format.line_spacing=1.05
                for rr in para.runs:
                    rr.font.name='Arial';rr.font.size=Pt(9.5)
                    if i==0:rr.bold=True;rr.font.color.rgb=RGBColor(255,255,255)
    doc.add_paragraph().paragraph_format.space_after=Pt(0)
    return t

